// Retires the service worker registered by the old Jekyll (Chirpy) site at /sw.min.js.
// Browsers that still have it pick up this version on their next visit: it clears the
// old caches, unregisters itself and reloads open tabs so they get the current site.
self.addEventListener('install', () => self.skipWaiting());

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const keys = await caches.keys();
      await Promise.all(keys.map((key) => caches.delete(key)));
      await self.registration.unregister();
      const clients = await self.clients.matchAll({ type: 'window' });
      clients.forEach((client) => client.navigate(client.url));
    })()
  );
});
